package es.riegocerca.maps;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import android.widget.Toast;
public class MainActivity extends Activity{WebView w;ValueCallback<Uri[]> files;GeolocationPermissions.Callback geo;String origin;static final int LOC=7,FILE=8;
 public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);
 w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){Uri x=Uri.parse(u);String h=x.getHost();if(u.startsWith("google.navigation:")||u.startsWith("geo:")||"www.google.com".equals(h)||"maps.google.com".equals(h)){openMaps(x);return true;}return false;}});
 w.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){origin=o;geo=c;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED){c.invoke(o,true,true);geo=null;}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=c;Intent i=p.createIntent();i.setType("*/*");try{startActivityForResult(i,FILE);return true;}catch(Exception e){files=null;return false;}}});if(b==null)w.loadUrl("file:///android_asset/index.html");else w.restoreState(b);}
 private void openMaps(Uri req){String d=req.getQueryParameter("destination");Uri nativeUri=req;if(d!=null&&!d.trim().isEmpty())nativeUri=Uri.parse("google.navigation:q="+Uri.encode(d)+"&mode=d");Intent i=new Intent(Intent.ACTION_VIEW,nativeUri);i.setPackage("com.google.android.apps.maps");try{startActivity(i);}catch(ActivityNotFoundException e){Uri f=d!=null?Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+Uri.encode(d)+"&travelmode=driving"):Uri.parse("https://www.google.com/maps");try{startActivity(new Intent(Intent.ACTION_VIEW,f));}catch(Exception ex){Toast.makeText(this,"No se pudo abrir Google Maps",Toast.LENGTH_LONG).show();}}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC&&geo!=null){boolean ok=false;for(int x:g)ok|=x==PackageManager.PERMISSION_GRANTED;geo.invoke(origin,ok,true);geo=null;origin=null;}}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==FILE&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(c,d));files=null;}}
 public void onBackPressed(){if(w.canGoBack())w.goBack();else super.onBackPressed();}protected void onSaveInstanceState(Bundle b){w.saveState(b);super.onSaveInstanceState(b);}}
